import {CheckmarkIcon} from '@sanity/icons/Checkmark'
import {ChevronDownIcon} from '@sanity/icons/ChevronDown'
import {
  // oxlint-disable-next-line no-restricted-imports -- the trigger lays out icon + title + chevron as custom children, which the studio Button wrapper does not support (same as WorkspaceMenuButton)
  Button as UIButton,
  Spinner,
} from '@sanity/ui'
import {Menu} from '@sanity/ui/menu'
import {type ComponentProps, type ComponentType, type CSSProperties, useId} from 'react'
import {Text, Box, Flex, Icon} from 'ui5'

import {MenuButton, type MenuButtonProps} from '../../../../ui-components/menuButton/MenuButton'
import {MenuItem} from '../../../../ui-components/menuItem/MenuItem'
import {menuButton} from './ConditionMenuButton.css.ts'
/**
 * One entry in a condition dropdown: a configured condition key, or one of its values.
 *
 * @internal
 */
export interface ConditionMenuOption {
  value: string
  title: string
  description?: string
  icon?: ComponentType
}

interface ConditionMenuOwnProps {
  onSelect: (value: string) => void
  options: readonly ConditionMenuOption[]
  selected?: ConditionMenuOption
  /**
   * Base test id. The trigger gets `${testId}-menu-button`, the list `${testId}-menu`, and each
   * row `${testId}-option-${value}`.
   */
  testId: string
}

/**
 * `MenuButton` wires the list up by cloning the `menu` element with `onItemClick`, `onEscape`,
 * `aria-labelledby` and friends, so the wrapper must forward the remaining `Menu` props.
 */
type ConditionMenuProps = ConditionMenuOwnProps &
  Omit<ComponentProps<typeof Menu>, 'children' | 'onSelect' | 'selected'>

interface ConditionMenuButtonProps extends ConditionMenuOwnProps {
  disabled?: boolean
  invalid?: boolean
  /** Stable field name. Stays in the accessible name after a value is chosen. */
  label: string
  loading?: boolean
  placeholder: string
  /** Id of the error text for this trigger. Set while `invalid` is true. */
  describedBy?: string
}

const POPOVER_PROPS: MenuButtonProps['popover'] = {
  constrainSize: true,
  fallbackPlacements: ['top-start'],
  matchReferenceWidth: true,
  placement: 'bottom-start',
  tone: 'default',
}

/**
 * The list behind a condition dropdown. Rows follow the workspace switcher: icon, title, and
 * description, with the current choice pressed and checked.
 *
 * @internal
 */
export function ConditionMenu(props: ConditionMenuProps): React.JSX.Element {
  const {onSelect, options, selected, testId, ...menuProps} = props

  return (
    <Menu data-testid={`${testId}-menu`} {...menuProps}>
      {options.map((option) => {
        const isSelected = option.value === selected?.value

        return (
          <MenuItem
            data-testid={`${testId}-option-${option.value}`}
            icon={option.icon}
            iconRight={isSelected ? CheckmarkIcon : undefined}
            key={option.value}
            onClick={isSelected ? undefined : () => onSelect(option.value)}
            pressed={isSelected}
            selected={isSelected}
            text={option.title}
            __unstable_subtitle={option.description}
          />
        )
      })}
    </Menu>
  )
}

/**
 * A select-like dropdown for one half of a condition (the key or its value). The trigger keeps a
 * single line in every state so picking never shifts the surrounding form; the options open in a
 * popover the width of the trigger.
 *
 * @internal
 */
export function ConditionMenuButton(props: ConditionMenuButtonProps): React.JSX.Element {
  const {
    disabled = false,
    describedBy,
    invalid = false,
    label,
    loading = false,
    onSelect,
    options,
    placeholder,
    selected,
    testId,
  } = props
  const id = useId()
  const SelectedIcon = selected?.icon
  const accessibleName = `${label}, ${selected ? selected.title : placeholder}`

  return (
    <MenuButton
      button={
        <UIButton
          aria-describedby={describedBy}
          aria-invalid={invalid ? 'true' : undefined}
          aria-label={accessibleName}
          data-testid={`${testId}-menu-button`}
          disabled={disabled || loading}
          mode="ghost"
          padding={3}
          tone={invalid ? 'critical' : 'default'}
          width="fill"
          className={menuButton}
        >
          <Flex alignItems="center" gap={3}>
            {SelectedIcon ? (
              <Icon
                icon={SelectedIcon}
                size={1}
                style={
                  {'margin': '-0.375rem', '--icon-color': 'var(--card-icon-color)'} as CSSProperties
                }
              />
            ) : null}
            <Box flexGrow={1}>
              <Text
                muted={!selected || invalid}
                size={1}
                truncate={1}
                weight="medium"
                as="div"
                trim={true}
                tone={invalid ? 'critical' : undefined}
                style={disabled || loading ? {color: 'var(--inert-foreground)'} : {}}
              >
                {selected ? selected.title : placeholder}
              </Text>
            </Box>
            {loading ? (
              <Spinner size={1} />
            ) : (
              <Icon
                icon={ChevronDownIcon}
                size={1}
                style={
                  {'margin': '-0.375rem', '--icon-color': 'var(--card-icon-color)'} as CSSProperties
                }
              />
            )}
          </Flex>
        </UIButton>
      }
      id={id}
      menu={
        <ConditionMenu onSelect={onSelect} options={options} selected={selected} testId={testId} />
      }
      popover={POPOVER_PROPS}
    />
  )
}
